arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *sername*) printf 'x-access-token' ;;
  *assword*) printf '%s' "$GITHUB_TOKEN" ;;
  *) printf '%s' "$GITHUB_TOKEN" ;;
esac
EOF
chmod 700 /tmp/askpass.sh
cd /tmp/wt-rachel && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin friend/rachel 2>&1 | sed -E 's/[A-Za-z0-9_]{20,}/[redacted]/g' | tail -4
